from pathlib import Path

INDEX_MARK='SJIT_HISTORY_QUERY_FIXED_V3'
INDEX_JS=r'''<script>/* SJIT_HISTORY_QUERY_FIXED_V3 */(()=>{const state={rows:[],page:1,size:20},$=id=>document.getElementById(id);let busy=false;const esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));function active(){return $('history')?.classList.contains('active')}function controls(){const h=$('history');if(!h)return null;const d=[...h.querySelectorAll('input[type=date]')],text=h.querySelector('#search')||h.querySelector('input[type=text]'),rs=h.querySelector('#filterResult')||[...h.querySelectorAll('select')].find(x=>[...x.options].some(o=>/PASS|FAIL|All Result/.test(o.textContent||''))),t=h.querySelector('table.table')||h.querySelector('table');return{h,d,text,rs,t}}async function load(){const c=controls(),S=window.sb;if(!c||!S||busy)return;busy=true;try{const from=c.d[0]?.value||'0000-01-01',to=c.d[1]?.value||'9999-12-31',q=await S.from('daily_inspections').select('inspection_date,customer,part_no,part_name,lot_no,in_qty,test_qty,bad_qty,result,inspector').gte('inspection_date',from).lte('inspection_date',to).order('inspection_date',{ascending:false});if(q.error)throw q.error;const term=(c.text?.value||'').trim().toLowerCase(),rf=c.rs?.value||'';state.rows=(q.data||[]).filter(x=>(!term||[x.customer,x.part_no,x.part_name,x.lot_no].join(' ').toLowerCase().includes(term))&&(!rf||String(x.result||'').toUpperCase()===String(rf).toUpperCase()));state.page=1;render()}catch(e){console.error('history query fixed',e)}finally{busy=false}}function render(){const c=controls();if(!c?.t)return;const b=c.t.tBodies[0];if(!b)return;const total=state.rows.length,pages=Math.max(1,Math.ceil(total/state.size));if(state.page>pages)state.page=pages;const start=(state.page-1)*state.size,end=Math.min(start+state.size,total);b.innerHTML=state.rows.slice(start,end).map(x=>`<tr><td>${esc(x.inspection_date)}</td><td>${esc(x.customer)}</td><td>${esc(x.part_no)}</td><td>${esc(x.part_name)}</td><td>${esc(x.lot_no)}</td><td>${Number(x.in_qty||0).toLocaleString()}</td><td>${Number(x.test_qty||0).toLocaleString()}</td><td>${Number(x.bad_qty||0).toLocaleString()}</td><td>${x.test_qty?((Number(x.bad_qty||0)/Number(x.test_qty||0))*100).toFixed(2):'0.00'}%</td><td><span class="badge ${String(x.result||'PASS').toUpperCase()==='FAIL'?'fail':'pass'}">${String(x.result||'PASS').toUpperCase()==='FAIL'?'FAIL':'PASS'}</span></td><td>${esc(x.inspector||'-')}</td></tr>`).join('')||'<tr><td colspan="11" class="empty">검색된 검사 이력이 없습니다.</td></tr>';let nav=c.t.parentElement.querySelector('.history-pagination');if(!nav){nav=document.createElement('div');nav.className='history-pagination';c.t.parentElement.appendChild(nav)}nav.innerHTML='';const info=document.createElement('div');info.className='history-pagination-info';info.textContent=`${total?start+1:0}-${end} / ${total}건`;const box=document.createElement('div');box.className='history-pagination-pages';const add=(txt,p,dis,act)=>{const z=document.createElement('button');z.type='button';z.textContent=txt;z.disabled=dis;if(act)z.className='active';z.onclick=()=>{state.page=p;render()};box.appendChild(z)};add('‹',Math.max(1,state.page-1),state.page===1,false);const list=pages<=7?Array.from({length:pages},(_,i)=>i+1):[1,...(state.page>4?['…']:[]),...Array.from({length:Math.max(0,Math.min(pages-1,state.page+1)-Math.max(2,state.page-1)+1)},(_,i)=>Math.max(2,state.page-1)+i),...(state.page<pages-3?['…']:[]),pages];list.forEach(x=>x==='…'?box.insertAdjacentHTML('beforeend','<span class="dots">…</span>'):add(String(x),x,false,x===state.page));add('›',Math.min(pages,state.page+1),state.page===pages,false);const sz=document.createElement('div');sz.className='history-pagination-size';sz.innerHTML='페이지당 <select><option>20</option><option>50</option><option>100</option></select>건';const sel=sz.querySelector('select');sel.value=String(state.size);sel.onchange=()=>{state.size=Number(sel.value)||20;state.page=1;render()};nav.append(info,box,sz)}function bind(){const c=controls();if(!c)return;const search=[...c.h.querySelectorAll('button')].find(b=>/조회|검색|Search|Tìm kiếm/.test((b.innerText||'').trim())&&!/Excel|CSV|초기화|Xóa/.test(b.innerText||''));if(search&&!search.dataset.queryFixed){search.dataset.queryFixed='1';search.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();load()},{capture:true})}c.d.forEach(x=>{if(!x.dataset.queryFixed){x.dataset.queryFixed='1';x.addEventListener('change',load)}});if(c.text&&!c.text.dataset.queryFixed){c.text.dataset.queryFixed='1';c.text.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();load()}})}}function tick(){if(active()){bind();load()}}document.addEventListener('click',e=>{if(e.target.closest?.('[data-page="history"]'))setTimeout(tick,250)});setInterval(()=>{if(active())bind()},1000);setTimeout(tick,900)})();</script>'''

VI_MARK='SJIT_VI_EXTRA_V3'
VI_JS=r'''<script>/* SJIT_VI_EXTRA_V3 */(()=>{const M={'Inspection History':'Lịch sử kiểm tra','검사 이력 조회 · Excel 일괄 업로드':'Tra cứu lịch sử kiểm tra · Tải Excel hàng loạt','Maker / Part / LOT':'Nhà cung cấp / Mã Part / Số LOT','All Result':'Tất cả kết quả','Excel 업로드':'Tải Excel','기간 조회':'Tra cứu theo thời gian','오늘':'Hôm nay','최근 7일':'7 ngày gần nhất','이번 달':'Tháng này','지난 달':'Tháng trước','조회':'Tra cứu','CSV':'CSV','페이지당':'Mục mỗi trang','건':'mục','검사 이력 조회':'Tra cứu lịch sử kiểm tra','검사 이력 · Excel 일괄 업로드':'Lịch sử kiểm tra · Tải Excel hàng loạt','Daily Inspection Dashboard':'Bảng điều khiển kiểm tra hàng ngày','Quality Management':'Quản lý chất lượng','월별 품질 현황':'Tình hình chất lượng theo tháng','전체':'Tất cả','PASS':'ĐẠT (PASS)','FAIL':'KHÔNG ĐẠT (FAIL)','검색된 검사 이력이 없습니다.':'Không tìm thấy lịch sử kiểm tra.','조회된 검사 이력이 없습니다.':'Không có lịch sử kiểm tra được tìm thấy.','초기화':'Đặt lại','Date':'Ngày','Part No.':'Mã Part','Part Name':'Tên vật liệu','LOT':'Số LOT','In':'Nhập','Test':'Kiểm tra','Defect':'Lỗi','Rate':'Tỷ lệ','Result':'Kết quả','Inspector':'Nhân viên kiểm tra','검사 LOT 수':'Số LOT kiểm tra','검사 수량':'Số lượng kiểm tra','불량 수량':'Số lượng lỗi'};const f=document.getElementById('appFrame');function go(){const d=f.contentDocument;if(!d?.body)return;const w=d.createTreeWalker(d.body,NodeFilter.SHOW_TEXT),a=[];let n;while(n=w.nextNode()){const p=n.parentElement;if(!p||p.tagName==='SCRIPT'||p.tagName==='STYLE')continue;const raw=n.nodeValue.trim(),out=M[raw];if(out&&out!==raw)a.push([n,raw,out])}a.forEach(([n,r,o])=>n.nodeValue=n.nodeValue.replace(r,o));d.querySelectorAll('input,button,select').forEach(e=>['placeholder','title','aria-label'].forEach(k=>{const v=e.getAttribute(k);if(v&&M[v])e.setAttribute(k,M[v])}));d.documentElement.lang='vi';d.title='SJIT VINA · Quản lý chất lượng';const b=d.getElementById('langBtn');if(b){b.textContent='🇰🇷 한국어';b.onclick=()=>window.top.location.href='./index.html'}}f.addEventListener('load',()=>{go();setTimeout(go,300);setTimeout(go,900)});setInterval(go,1000)})();</script>'''

p=Path('daily-inspection/index.html');s=p.read_text(encoding='utf-8')
if INDEX_MARK not in s:
    s=s.replace('</body></html>',INDEX_JS+'</body></html>')
    p.write_text(s,encoding='utf-8')
p=Path('daily-inspection/vi.html');s=p.read_text(encoding='utf-8')
if VI_MARK not in s:
    s=s.replace('</body>\n</html>',VI_JS+'</body>\n</html>')
    p.write_text(s,encoding='utf-8')

